model_name = arguments.get('model')
if not model_name or model_name not in env:
    result = {'error': 'Model %r not found' % model_name}
else:
    operations = ['read', 'write', 'create', 'unlink']
    rights = {}
    for op in operations:
        try:
            env[model_name].check_access(op)
            rights[op] = True
        except Exception:
            rights[op] = False
    rules = env['ir.model.access'].sudo().search_read(
        [('model_id.model', '=', model_name)],
        fields=[
            'name', 'group_id', 'perm_read', 'perm_write',
            'perm_create', 'perm_unlink',
        ],
    )
    result = {
        'model': model_name,
        'current_user_rights': rights,
        'access_rules': rules,
    }

{
    "type": "object",
    "properties": {
        "model": {
            "type": "string",
            "description": "Technical model name (e.g. 'sale.order')."
        }
    },
    "required": ["model"]
}

model_name = arguments.get('model')
if not model_name or model_name not in env:
    result = {'error': 'Model %r not found' % model_name}
else:
    domain = arguments.get('domain', [])
    fields_list = arguments.get('fields', [])
    groupby = arguments.get('groupby', [])
    if not groupby:
        result = {'error': 'groupby is required'}
    else:
        model = env[model_name]
        model_fields = model.fields_get()
        aggregates = []
        numeric_types = {'integer', 'float', 'monetary'}
        for field_spec in fields_list:
            if ':' in field_spec:
                aggregates.append(field_spec)
                continue
            if field_spec in groupby:
                continue
            field_info = model_fields.get(field_spec, {})
            if field_info.get('type') in numeric_types:
                aggregates.append('%s:sum' % field_spec)
            else:
                aggregates.append('%s:count_distinct' % field_spec)
        if '__count' not in aggregates:
            aggregates.append('__count')
        data = model.formatted_read_group(
            domain,
            groupby=groupby,
            aggregates=aggregates,
            limit=arguments.get('limit'),
            order=arguments.get('order') or None,
        )
        for row in data:
            if '__count' in row:
                row['%s_count' % groupby[0]] = row.pop('__count')
        result = data

