model_name = arguments.get('model')
if not model_name or model_name not in env:
    result = {'error': 'Model %r not found' % model_name}
else:
    method_name = arguments.get('method')
    if not method_name:
        result = {'error': 'No method name provided'}
    elif method_name.startswith('_'):
        result = {'error': 'Private methods cannot be called: %r' % method_name}
    else:
        ids = arguments.get('ids', [])
        if isinstance(ids, int):
            ids = [ids]
        args = arguments.get('args', [])
        kwargs = arguments.get('kwargs', {})
        model = env[model_name]
        if ids:
            model = model.browse(ids)
        method = getattr(model, method_name, None)
        if method is None:
            result = {'error': 'Method %r not found on %r' % (method_name, model_name)}
        else:
            result = method(*args, **kwargs)

